// Bài 1.1 — máy trạng thái: ngoài nháy / trong nháy; "started" để giữ được đối số rỗng ""
function splitArgs(line) {
  const args = [];
  let cur = '', started = false, quote = null;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (quote) {
      if (ch === quote) quote = null; else cur += ch;
    } else if (ch === '"' || ch === "'") {
      quote = ch; started = true;
    } else if (ch === '\\' && i + 1 < line.length) {
      cur += line[++i]; started = true;
    } else if (ch === ' ' || ch === '\t') {
      if (started) { args.push(cur); cur = ''; started = false; }
    } else {
      cur += ch; started = true;
    }
  }
  if (quote) throw new SyntaxError('unterminated quote');
  if (started) args.push(cur);
  return args;
}

